// FORWARD / RETURN at the purchase's stage; FORWARD checks that the stage's
// work is done:
//
//	FORMING              impl. head  FORWARD (assignee given) → SPECIFICATION
//	SPECIFICATION        assignee    FORWARD (characteristics, ≥1 КП) → SPECIFICATION_CHECK; RETURN → FORMING
//	SPECIFICATION_CHECK  impl. head  FORWARD (codes filled) → CURATOR_REVIEW; RETURN → SPECIFICATION
//	CURATOR_REVIEW       curator     FORWARD (justification) → ECONOMIST_REVIEW; RETURN → SPECIFICATION_CHECK
//	ECONOMIST_REVIEW     economist   FORWARD (funding, КОСГУ, НМЦК) → BUDGET_COMMISSION; RETURN → CURATOR_REVIEW
//	BUDGET_COMMISSION    commission  only by PurchaseProtocolCreate
//	APPROVED             impl. head  FORWARD (assignee given) → TECH_SPEC
//	TECH_SPEC            assignee    FORWARD (ТЗ) → TECH_SPEC_CHECK; RETURN → APPROVED
//	TECH_SPEC_CHECK      impl. head  FORWARD → TECH_SPEC_CURATOR; RETURN → TECH_SPEC
//	TECH_SPEC_CURATOR    curator     FORWARD → FINAL_COST; RETURN → TECH_SPEC_CHECK
//	FINAL_COST           economist   FORWARD (final cost) → CONTRACT_SERVICE; RETURN → TECH_SPEC_CURATOR
//	CONTRACT_SERVICE     contract    FORWARD (law, method) → PROCUREMENT; RETURN → FINAL_COST
//	PROCUREMENT          procurement FORWARD → TENDERING; RETURN → CONTRACT_SERVICE
//	TENDERING            procurement FORWARD (supplier) → CONTRACTING; RETURN → PROCUREMENT
//	CONTRACTING          procurement FORWARD (contract №, date, amount) → DELIVERY; RETURN → TENDERING
//	DELIVERY             procurement FORWARD (delivered) → ACCEPTANCE; RETURN → CONTRACTING
//	ACCEPTANCE           acceptance  FORWARD (accepted) → INVENTORY, a service → COMPLETED; RETURN → DELIVERY
//	INVENTORY            inventory   FORWARD (≥1 item) → COMPLETED; RETURN → ACCEPTANCE
